<?php $canDeleteMovement=$admin && $page==='movimentacoes'; ?>
<div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Equipamento</th><th>Funcionário / destino</th><th>Quantidade</th><th>Data</th><th>Motivo</th><?php if($canDeleteMovement): ?><th>Ação</th><?php endif ?></tr></thead><tbody><?php foreach($history as $h): ?><tr><td><span class="badge <?= $h['tipo']==='Entrada'?'success':'info' ?>"><?= e($h['tipo']) ?></span></td><td><?= e($h['nome_epi']) ?></td><td><?= e($h['nome_completo']) ?></td><td><?= (int)$h['quantidade'] ?></td><td><?= e(date('d/m/Y',strtotime($h['data']))) ?></td><td class="long-text"><?= e($h['motivo']) ?></td><?php if($canDeleteMovement): ?><td><form method="post" action="excluirmovimentacao.php" data-confirm="Excluir este registro do histórico? O saldo atual do estoque não será alterado. Uma saída excluída também deixa de aparecer nos equipamentos recebidos do funcionário."><?= csrf() ?><input type="hidden" name="id_movimentacao" value="<?= (int)$h['id'] ?>"><input type="hidden" name="tipo" value="<?= e($h['tipo']) ?>"><button class="button secondary small danger-text" type="submit">Excluir</button></form></td><?php endif ?></tr><?php endforeach; if(!$history): ?><tr><td colspan="<?= $canDeleteMovement?7:6 ?>" class="empty">Nenhuma movimentação registrada.</td></tr><?php endif ?></tbody></table></div>
